<span class="line"><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">  --data-urlencode</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;app=camera&quot;</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> \\</span></span>
